#include <string>

class Solution {
public:
    bool isValid(std::string s) {
        if (s.length() % 2 != 0) return false;

        bool changed = true;
        while (changed) {
            changed = false;
            size_t pos;
            if ((pos = s.find("()")) != std::string::npos) {
                s.erase(pos, 2);
                changed = true;
            } else if ((pos = s.find("[]")) != std::string::npos) {
                s.erase(pos, 2);
                changed = true;
            } else if ((pos = s.find("{}")) != std::string::npos) {
                s.erase(pos, 2);
                changed = true;
            }
        }
        return s.empty();
    }
};

#include <string>
#include <stack>

class Solution {
public:
    bool isValid(const std::string& s) {
        // An odd length string can never be balanced
        if (s.length() % 2 != 0) return false;

        std::stack<char> st;

        for (char c : s) {
            if (c == '(') {
                st.push(')');
            } else if (c == '[') {
                st.push(']');
            } else if (c == '{') {
                st.push('}');
            } else {
                // Closing bracket: stack must not be empty and top must match
                if (st.empty() || st.top() != c) {
                    return false;
                }
                st.pop();
            }
        }

        // Must be completely matched (stack empty)
        return st.empty();
    }
};
